<?php
defined('ABSPATH') || exit; get_header();
$title = is_search() ? 'Kết quả cho “' . get_search_query() . '”' : 'Kiến thức & kinh nghiệm';
?>
<div class="container"><?php if (!is_home()) { hpv_breadcrumbs(); } ?></div><section class="page-intro container"><span class="section-kicker"><?php echo is_search() ? 'Tìm kiếm trên website' : 'Cẩm nang Hải Phát Vina'; ?></span><h1><?php echo esc_html($title); ?></h1><p><?php echo is_search() ? 'Chọn nội dung bên dưới hoặc thử tìm bằng từ khóa khác.' : 'Hiểu vật liệu, cân nhắc quy cách và tìm ý tưởng cho không gian của bạn. Những điều nên biết trước khi lựa chọn.'; ?></p><?php if (is_search()) { get_search_form(); } else { $topics = get_categories(array('hide_empty' => true)); if ($topics) { echo '<nav class="topic-links" aria-label="Chuyên mục bài viết">'; foreach ($topics as $topic) { echo '<a href="' . esc_url(get_category_link($topic->term_id)) . '">' . esc_html(hpv_category_label($topic)) . '</a>'; } echo '</nav>'; } } ?></section>
<section class="section archive-section"><div class="container"><div class="article-grid"><?php if (have_posts()) { while (have_posts()) { the_post(); if (get_post_type() === 'hpv_product') { get_template_part('template-parts/product-card'); } elseif (get_post_type() === 'hpv_project') { get_template_part('template-parts/project-card'); } else { get_template_part('template-parts/article-card'); } } } else { ?><div class="empty-state"><h2>Chưa tìm thấy nội dung phù hợp</h2><p>Thử một từ khóa ngắn hơn như “mái xếp”, “bạt” hoặc “dù che”.</p><a class="button button--navy" href="<?php echo esc_url(hpv_products_url()); ?>">Xem danh mục sản phẩm</a></div><?php } ?></div><?php the_posts_pagination(array('prev_text' => 'Trang trước', 'next_text' => 'Trang sau')); ?></div></section>
<?php get_footer(); ?>
